import { useState, useEffect } from 'react';
import { clientService } from '../services/clientService';
import { projectService } from '../services/projectService';
import { documentService } from '../services/documentService';
import { useAuth } from '../contexts/AuthContext';

export const useDashboardData = () => {
  const { user } = useAuth();
  const [stats, setStats] = useState({});
  const [clients, setClients] = useState([]);
  const [projects, setProjects] = useState([]);
  const [documents, setDocuments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);

      // Los clientes NO deben cargar la lista de clientes
      const isClient = user?.role === 'client';

      if (isClient) {
        // Cliente: Solo carga proyectos y documentos
        const [projectsData, documentsData] = await Promise.all([
          projectService.getAll().catch(err => {
            console.error('Error loading projects:', err);
            return [];
          }),
          documentService.getAll().catch(err => {
            console.error('Error loading documents:', err);
            return [];
          }),
        ]);

        setClients([]); // Los clientes no ven la lista de clientes
        setProjects(projectsData);
        setDocuments(documentsData);

        // Estadísticas para clientes
        setStats({
          total_clients: 0,
          total_projects: projectsData.length,
          active_projects: projectsData.filter(p => p.status === 'in_progress').length,
          total_documents: documentsData.length,
        });
      } else {
        // Admin, User, Super Admin: Cargan todo
        const [clientsData, projectsData, documentsData] = await Promise.all([
          clientService.getAll().catch(err => {
            console.error('Error loading clients:', err);
            return [];
          }),
          projectService.getAll().catch(err => {
            console.error('Error loading projects:', err);
            return [];
          }),
          documentService.getAll().catch(err => {
            console.error('Error loading documents:', err);
            return [];
          }),
        ]);

        setClients(clientsData);
        setProjects(projectsData);
        setDocuments(documentsData);

        // Estadísticas para admin/user
        setStats({
          total_clients: clientsData.length,
          total_projects: projectsData.length,
          active_projects: projectsData.filter(p => p.status === 'in_progress').length,
          total_documents: documentsData.length,
        });
      }
    } catch (err) {
      console.error('Error fetching dashboard data:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user) {
      fetchData();
    }
  }, [user]);

  return {
    stats,
    clients,
    projects,
    documents,
    loading,
    error,
    refetch: fetchData,
  };
};
